"""Pydantic models: the data contracts of the application.

Facts (documented, with source) stay strictly separate from the LLM's
assessment. Every suggestion must reference fact IDs that exist, so the
UI can show what each suggestion builds on.
"""
from datetime import datetime
from typing import Literal
from pydantic import BaseModel, ConfigDict, Field, field_validator



class Fact(BaseModel):
    """One documented fact with its public source. Never generated by the LLM."""
    fact_id: str                       # e.g. "brreg:name", "websearch:text"
    source: Literal["brreg", "website", "websearch"]
    source_url: str
    label: str                         # human-readable field name
    value: str                         # the fact itself
    retrieved_at: datetime


class SourceStatus(BaseModel):
    source: Literal["brreg", "website", "websearch"]
    url: str
    status: Literal["ok", "unavailable", "failed"]
    detail: str = ""


class UseCase(BaseModel):
    """One AI opportunity suggested by the LLM.

    extra="forbid": fields the model invents beyond the contract are
    rejected, not silently dropped.
    """
    model_config = ConfigDict(extra="forbid")

    title: str = Field(min_length=3, max_length=120)
    description: str = Field(min_length=20)
    expected_value: str = Field(min_length=10)
    based_on_fact_ids: list[str]       # must reference existing facts
    is_assessment: Literal[True] = True  # explicit marker: this is the LLM's opinion


class Analysis(BaseModel):
    """The full, saved result for one organisation number."""
    orgnr: str
    company_name: str
    generated_at: datetime
    model: str                         # which LLM produced the assessment
    sources: list[SourceStatus]
    facts: list[Fact]
    use_cases: list[UseCase]           # all flagged is_assessment=True
    limitations: list[str]

    @field_validator("orgnr")
    @classmethod
    def orgnr_is_nine_digits(cls, v: str) -> str:
        digits = v.replace(" ", "")
        if not (len(digits) == 9 and digits.isdigit()):
            raise ValueError("orgnr must be 9 digits")
        return digits


class LLMOutput(BaseModel):
    """Strict schema the LLM must return, validated before use.

    extra="forbid" rejects unexpected top-level keys like any other
    violation.
    """
    model_config = ConfigDict(extra="forbid")

    use_cases: list[UseCase] = Field(min_length=2, max_length=3)
    limitations: list[str] = Field(min_length=1)


def validate_llm_output(data: dict, known_fact_ids: set[str]) -> LLMOutput:
    """Validate the LLM's raw JSON: schema and fact references.

    Raises ValueError with a readable reason if the model invents fact
    IDs or breaks the format; the caller may then retry once.
    """
    parsed = LLMOutput.model_validate(data)
    for uc in parsed.use_cases:
        unknown = [fid for fid in uc.based_on_fact_ids if fid not in known_fact_ids]
        if unknown:
            raise ValueError(
                f"LLM referenced unknown fact IDs: {unknown}. "
                "Only IDs from the fact registry are allowed."
            )
        if not uc.based_on_fact_ids:
            raise ValueError(f"Use case '{uc.title}' cites no facts - rejected.")
        if not any(fid.startswith("brreg:") for fid in uc.based_on_fact_ids):
            raise ValueError(
                f"Use case '{uc.title}' cites no Brreg fact. "
                "Every suggestion must cite a relevant registry fact, "
                "not just website content."
            )
    return parsed
